/**
 * Period-average FX conversion to USD (build-time only; imports the committed JSON).
 *
 * Rates in src/data/fx/usd-rates.json are units of currency per 1 USD, averaged over each
 * calendar month, quarter and year (generated by scripts/fetch-fx.ts).
 *
 *   toUsd(1270380, 'TWD', '2026-Q2')                       // calendar quarter average
 *   toUsd(514805, 'TWD', '2026-08')                        // monthly average
 *   toUsd(3809054, 'TWD', '2025')                          // annual average
 *   toUsd(732388, 'JPY', { start: '2026-04-01', end: '2026-06-30' })  // any date range
 *
 * Arbitrary ranges use a day-weighted average of the monthly averages they overlap, so
 * non-calendar fiscal quarters (NVIDIA, Micron…) get their own period average.
 */
import raw from '../data/fx/usd-rates.json';
import type { CurrencyCode } from './format';
import { formatMoney, formatNumber, zhConcat } from './format';
import { dayNumber, overlapDays } from './fiscal';

export interface FxSource {
  provider: string;
  series: string;
  url: string;
  method: string;
  inverted: boolean;
  accessed: string;
  fallbackFrom?: string;
  note?: string;
}

interface FxCurrency {
  nameZh: string;
  source: FxSource;
  observations: number;
  firstObservation: string | null;
  lastObservation: string | null;
  partial: string[];
  monthly: Record<string, number>;
  quarterly: Record<string, number>;
  annual: Record<string, number>;
}

interface FxFile {
  base: 'USD';
  quote: string;
  generated: string;
  coverage: { from: string; to: string };
  method: string;
  currencies: Record<string, FxCurrency>;
}

const FX = raw as unknown as FxFile;

export const FX_GENERATED: string = FX.generated;
export const FX_COVERAGE: { from: string; to: string } = FX.coverage;
export const FX_METHOD: string = FX.method;

/** Currencies with rates (USD is implicit, rate 1). */
export function fxCurrencies(): string[] {
  return Object.keys(FX.currencies);
}

export function fxSource(currency: string): FxSource | null {
  return FX.currencies[currency]?.source ?? null;
}

/** A calendar key ('2026-08' | '2026-Q2' | '2026') or an inclusive date range. */
export type FxPeriod = string | { start: string; end: string };

export type RateMethod = 'identity' | 'month' | 'quarter' | 'year' | 'range';

export interface RateInfo {
  currency: string;
  /** units of currency per 1 USD */
  rate: number;
  method: RateMethod;
  /** human label of the averaging window: 「2026 Q2」「2026 年 8 月」「2026/4/27–7/26 期間」 */
  window: string;
  /** some months were outside the FX file and the nearest month's rate was used */
  extrapolated: boolean;
  /** the annual average covers only part of the year */
  partial: boolean;
}

const RE_M = /^(\d{4})-(0[1-9]|1[0-2])$/;
const RE_Q = /^(\d{4})-Q([1-4])$/;
const RE_Y = /^(\d{4})$/;

function monthEnd(ym: string): string {
  const [y, m] = ym.split('-').map(Number) as [number, number];
  return new Date(Date.UTC(y, m, 0)).toISOString().slice(0, 10);
}

function monthsBetween(start: string, end: string): string[] {
  const out: string[] = [];
  let [y, m] = start.slice(0, 7).split('-').map(Number) as [number, number];
  const [ey, em] = end.slice(0, 7).split('-').map(Number) as [number, number];
  while (y < ey || (y === ey && m <= em)) {
    out.push(`${y}-${String(m).padStart(2, '0')}`);
    m++;
    if (m > 12) {
      m = 1;
      y++;
    }
  }
  return out;
}

export interface RateOptions {
  /**
   * When part of the window falls after the FX file's coverage, use the latest monthly
   * average for those days (flagged `extrapolated`). Default true. Windows entirely before
   * coverage always return null.
   */
  extrapolate?: boolean;
}

function rangeRate(c: FxCurrency, start: string, end: string, extrapolate: boolean): { rate: number; extrapolated: boolean } | null {
  const months = monthsBetween(start, end);
  const keys = Object.keys(c.monthly).sort();
  const first = keys[0];
  const last = keys.at(-1);
  if (!first || !last) return null;
  let wSum = 0;
  let vSum = 0;
  let extrapolated = false;
  for (const ym of months) {
    const days = overlapDays(start, end, `${ym}-01`, monthEnd(ym));
    if (!days) continue;
    let v = c.monthly[ym];
    if (v == null) {
      if (ym > last && extrapolate) {
        v = c.monthly[last]!;
        extrapolated = true;
      } else continue;
    }
    wSum += days;
    vSum += v * days;
  }
  // require at least half of the window to be covered by real or extrapolated data
  const total = dayNumber(end) - dayNumber(start) + 1;
  if (!wSum || wSum < total / 2) return null;
  return { rate: vSum / wSum, extrapolated };
}

/** Full rate info for a currency and period, or null when no rate is available. */
export function rateInfo(currency: CurrencyCode | string, period: FxPeriod, opts: RateOptions = {}): RateInfo | null {
  const extrapolate = opts.extrapolate ?? true;
  if (currency === 'USD') {
    return { currency, rate: 1, method: 'identity', window: typeof period === 'string' ? period : `${period.start}–${period.end}`, extrapolated: false, partial: false };
  }
  const c = FX.currencies[currency];
  if (!c) return null;

  if (typeof period === 'string') {
    let m: RegExpExecArray | null;
    if ((m = RE_M.exec(period))) {
      const v = c.monthly[period];
      if (v != null) return { currency, rate: v, method: 'month', window: `${m[1]} 年 ${Number(m[2])} 月`, extrapolated: false, partial: false };
      const r = rangeRate(c, `${period}-01`, monthEnd(period), extrapolate);
      return r ? { currency, rate: r.rate, method: 'month', window: `${m[1]} 年 ${Number(m[2])} 月`, extrapolated: r.extrapolated, partial: false } : null;
    }
    if ((m = RE_Q.exec(period))) {
      const v = c.quarterly[period];
      const window = `${m[1]} Q${m[2]}`;
      if (v != null) return { currency, rate: v, method: 'quarter', window, extrapolated: false, partial: false };
      const q = Number(m[2]);
      const start = `${m[1]}-${String((q - 1) * 3 + 1).padStart(2, '0')}-01`;
      const end = monthEnd(`${m[1]}-${String(q * 3).padStart(2, '0')}`);
      const r = rangeRate(c, start, end, extrapolate);
      return r ? { currency, rate: r.rate, method: 'quarter', window, extrapolated: r.extrapolated, partial: false } : null;
    }
    if ((m = RE_Y.exec(period))) {
      const v = c.annual[period];
      const partial = c.partial.includes(period);
      if (v != null && !(partial && extrapolate === false)) {
        return { currency, rate: v, method: 'year', window: `${period} 年`, extrapolated: false, partial };
      }
      const r = rangeRate(c, `${period}-01-01`, `${period}-12-31`, extrapolate);
      return r ? { currency, rate: r.rate, method: 'year', window: `${period} 年`, extrapolated: r.extrapolated, partial } : null;
    }
    return null;
  }

  const { start, end } = period;
  // exact calendar windows use the stored averages of daily data
  const ys = start.slice(0, 4);
  if (start.endsWith('-01-01') && end === `${ys}-12-31`) return rateInfo(currency, ys, opts);
  const qm = Number(start.slice(5, 7));
  if (start.endsWith('-01') && (qm - 1) % 3 === 0) {
    const q = (qm - 1) / 3 + 1;
    const qEnd = monthEnd(`${ys}-${String(q * 3).padStart(2, '0')}`);
    if (end === qEnd) return rateInfo(currency, `${ys}-Q${q}`, opts);
  }
  if (start.endsWith('-01') && end === monthEnd(start.slice(0, 7))) return rateInfo(currency, start.slice(0, 7), opts);
  const r = rangeRate(c, start, end, extrapolate);
  if (!r) return null;
  const [sy, sm, sd] = start.split('-').map(Number);
  const [ey, em, ed] = end.split('-').map(Number);
  const window = sy === ey ? `${sy}/${sm}/${sd}–${em}/${ed}` : `${sy}/${sm}/${sd}–${ey}/${em}/${ed}`;
  return { currency, rate: r.rate, method: 'range', window, extrapolated: r.extrapolated, partial: false };
}

/** Units of `currency` per 1 USD for the period, or null. */
export function usdRate(currency: CurrencyCode | string, period: FxPeriod, opts: RateOptions = {}): number | null {
  return rateInfo(currency, period, opts)?.rate ?? null;
}

/** Convert an amount in millions of `currency` to millions of USD, or null when no rate exists. */
export function toUsd(valueMillions: number, currency: CurrencyCode | string, period: FxPeriod, opts: RateOptions = {}): number | null {
  if (!Number.isFinite(valueMillions)) return null;
  const r = usdRate(currency, period, opts);
  return r ? valueMillions / r : null;
}

/** Rate formatted for notes: 31.60 · 159.4 · 1,500 · 0.8598 */
export function formatRate(rate: number): string {
  const a = Math.abs(rate);
  const digits = a >= 1000 ? 0 : a >= 100 ? 1 : a >= 1 ? 2 : 4;
  return formatNumber(rate, { digits });
}

/**
 * 「≈ 402 億美元（以 2026 Q2 平均匯率 31.60 換算，僅供比較）」
 * Returns '' for USD amounts or when no rate is available.
 */
export function usdNote(valueMillions: number, currency: CurrencyCode | string, period: FxPeriod, opts: RateOptions = {}): string {
  if (currency === 'USD') return '';
  const info = rateInfo(currency, period, opts);
  if (!info) return '';
  const usd = valueMillions / info.rate;
  return `≈ ${formatMoney(usd, 'USD')}（${rateClause(info)}，僅供比較）`;
}

/** 「以 2026 Q2 平均匯率 31.60 換算」 */
export function rateClause(info: RateInfo): string {
  const window = info.method === 'range' ? `${info.window} 期間` : info.window;
  const extra = info.extrapolated ? '；部分月份以最新月均匯率估算' : info.partial ? '；年度至今平均' : '';
  return `${zhConcat('以', window, '平均匯率', formatRate(info.rate), '換算')}${extra}`;
}

/** One-line citation for the FX data, e.g. for chart source lines. */
export function fxCitation(currency: CurrencyCode | string): { title: string; url: string } | null {
  const s = fxSource(currency);
  if (!s) return null;
  return { title: `${s.provider}（${s.series}）`, url: s.url };
}
